-- ═══ Step 1: Course scaffold — module → subject → topics → past-paper tag ═══
-- Idempotent: ON CONFLICT DO UPDATE so the IDs are always resolvable on re-run.
DO $$
DECLARE
  v_module_id  uuid;
  v_subject_id uuid;
BEGIN
  INSERT INTO public.modules (name, name_np, slug, is_universal, exam_levels, display_order, price_paisa)
  VALUES ('TSC Nimavi First Paper', 'निमावि प्रथम पत्र (शिक्षक सेवा आयोग)', 'nimavi-pratham-patra',
          false, ARRAY['nimavi','prathamik'], 10, NULL)
  ON CONFLICT (slug) DO UPDATE SET name_np = EXCLUDED.name_np
  RETURNING id INTO v_module_id;

  -- Exam-oriented model/past papers — a distinct subject (NOT topic-wise practice),
  -- positioned as the last section (display_order 6) within the syllabus course.
  INSERT INTO public.subjects (module_id, name, name_np, slug, display_order)
  VALUES (v_module_id, 'Practice Question Papers', 'अभ्यास प्रश्न पत्र', 'abhyas', 6)
  ON CONFLICT (module_id, slug) DO UPDATE
    SET name = EXCLUDED.name, name_np = EXCLUDED.name_np, display_order = EXCLUDED.display_order
  RETURNING id INTO v_subject_id;

  INSERT INTO public.topics (subject_id, name, slug, display_order)
  VALUES (v_subject_id, 'मोडेल सेट', 'model-set', 1)
  ON CONFLICT (subject_id, slug) DO UPDATE SET display_order = EXCLUDED.display_order;

  INSERT INTO public.topics (subject_id, name, slug, display_order)
  VALUES (v_subject_id, 'विगतका प्रश्नपत्र', 'vigat-prashnapatra', 2)
  ON CONFLICT (subject_id, slug) DO UPDATE SET display_order = EXCLUDED.display_order;
END $$;

INSERT INTO public.tags (name, name_np, slug, color)
VALUES ('Past Paper', 'विगत प्रश्नपत्र', 'past-paper', '#b45309')
ON CONFLICT (slug) DO NOTHING;

