      (v_set_id, 46, E'दिए अनुसार खाली स्थान (?) मा कुन चाहिँ विकल्प उपयुक्त हुन्छ रोज्नुहोस् :\n[72  21  17]\n[54  32  26]\n[38  30   ?]', E'55', E'61', E'75', E'77', 'B', E'', 'nepali', false, NULL, NULL),
      (v_set_id, 47, E'3, 4, 5 फलफूलले एक प्याक बनाउँदा एकवटा फलफूल बाँकी रहन्छ। तर 11 ओटाको दरले प्याक बनाउँदा बाँकी रहँदैन भने न्यूनतम कति फलफूल छ ?', E'121', E'242', E'73', E'79', 'A', E'x ≡ 1 (mod 60) र x divisible by 11; minimum x = 121 (= 11 × 11)。', 'nepali', true, NULL, NULL),
      (v_set_id, 48, E'750 ग्राम पानीमा 250 ग्राम चिनी राखेर एउटा घोल बनाइएको छ। उक्त घोलमा भएको चिनी र पानीको अनुपात कति हुन्छ ?', E'5:7', E'1:3', E'7:5', E'2:7', 'B', E'चिनी : पानी = 250 : 750 = 1 : 3।', 'nepali', true, NULL, NULL),
      (v_set_id, 49, E'Which is the meaningful sentence from the given words: than/ are/ the/ poem/ two/ students/ recitation/ attending/ competition/ more.', E'The poem recitation competition are more than two students attending.', E'Two students are more than attending the poem recitation competition.', E'More than two students are attending the poem recitation competition.', E'More than two students are competition the poem recitation attending.', 'C', E'', 'english', true, NULL, NULL),
      (v_set_id, 50, E'Which word is different in the following word group?', E'Hard Work', E'Pleasure', E'Joyful', E'Delight', 'A', E'Pleasure, Joyful, Delight सबै आनन्द/खुसी अर्थका शब्द हुन्; Hard Work फरक हो।', 'english', true, NULL, NULL)
    RETURNING id, order_number
  )
  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- Surface in the topic list (unlocked — mock exams are not a gated sequence)
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;
  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% Qs)', E'निमावि प्रथम पत्र — मोडेल सेट १', 50;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- निमावि प्रथम पत्र — मोडेल सेट २  (50 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id  uuid;
  v_set_id    uuid;
  v_existing  uuid;
  v_next_step int;
BEGIN
  SELECT t.id INTO v_topic_id
  FROM public.topics t
  JOIN public.subjects s ON s.id = t.subject_id
  JOIN public.modules  m ON m.id = s.module_id
  WHERE m.slug = 'nimavi-pratham-patra' AND s.slug = 'abhyas' AND t.slug = 'model-set'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'Topic % not found (scaffold block must run first)', 'model-set';
  END IF;

  SELECT id INTO v_existing FROM public.question_sets
  WHERE title = E'निमावि प्रथम पत्र — मोडेल सेट २' AND topic_id = v_topic_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'निमावि प्रथम पत्र — मोडेल सेट २';
    RETURN;
  END IF;

  INSERT INTO public.question_sets (topic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, E'निमावि प्रथम पत्र — मोडेल सेट २', 2, 'mock_exam', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d,
