    VALUES
      (v_set_id, 1, E'बिग ब्याङ्ग सिद्धान्त (Big Bang Theory) अनुसार ब्रह्माण्डको आयु कति वर्ष भएको अनुमान गरिन्छ ?', E'१२.५ अर्ब वर्ष', E'साँढे १३.८ अर्ब वर्ष', E'१४ अर्ब वर्ष', E'१५ अर्ब वर्ष', 'B', E'सूर्यको केन्द्र बाहेक पृथ्वीतलमा अन्य ग्रह उपग्रहहरूले सूर्यको परिक्रमा गर्दछन् भन्ने तथ्य सार्वजनिक गर्ने व्यक्ति निकोलस कोपर्निकस हुन्।', 'nepali', true, NULL, NULL),
      (v_set_id, 2, E'एक देखि देशान्तरको फरकमा कति समयको फरकपन हुन्छ ?', E'४ मिनेट', E'६० मिनेट', E'१२० मिनेट', E'१५० मिनेट', 'A', E'पृथ्वीले १५° डिग्री देशान्तरमा एक समय फेरा बनाउँछ।', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'तलका भनाई विचार गर्नुहोस्।\nक. विश्वको सबैभन्दा ठूलो सुख्खा मरुभूमि अटाकामा हो।\nख. द ठेट भिक्टोरीयाा मरुभूमि अष्ट्रेलिया महादेशमा पर्दछ।\nग. चिहुवाहुआ मरुभूमि अमेरिकामा पर्दछ।\nघ. अरेबियन मरुभूमि एशियाको सबैभन्दा ठूलो उष्ण मरुभूमि हो।', E'क र घ ठीक, ख र ग बेठिक', E'ख र ग ठीक, क र घ बेठिक', E'ग मात्र ठिक, क र ख बेठिक', E'सबै ठिक', 'D', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'नेपालको सबैभन्दा पूर्वी बिन्दु ८८°१२'' पूर्वी देशान्तरलाई मानिन्छ, उक्त देशान्तरले छोएको जिल्ला कुन हो ?', E'ताप्लेजुङ', E'पाँचथर', E'इलाम', E'झापा', 'A', E'नेपालको सबैभन्दा उत्तरी बिन्दु हुम्ला जिल्लामा पर्दछ।', 'nepali', true, NULL, NULL),
      (v_set_id, 5, E'फेलुङ्गी पुलले कुन जिल्लालाई जिल्लासँग चिनिन्छ ?', E'ओखलढुंगा', E'बाग्लुङ', E'उदयपुर', E'जाजरकोट', 'B', E'तीन तिखारट तर्फबाट निमाण छुट्याइको जिल्ला ओखलढुंगा हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 6, E'सही जोडा मिलाउनुहोस्।\n(a) चाँदीको मोहर   (i) सिद्धिसिंह मल्ल\n(b) छालाको सिक्का   (ii) रत्नमल्ल\n(c) तामाको सिक्का   (iii) मानदेव\n(d) मानाङ   (iv) महेन्द्र मल्ल', E'a-iv, b-iii, c-i, d-ii', E'a-iv, b-i, c-iii, d-ii', E'a-iii, b-iv, c-i, d-ii', E'a-i, b-iii, c-iv, d-ii', 'C', E'मानव न्यायशास्त्र को लेखक जयस्थिति मल्ल हुन्।', 'nepali', true, NULL, NULL),
      (v_set_id, 7, E'किरात राजाहरू प्रमुखत: कुन धर्मावलम्बी भएको मानिन्छ ?', E'शैव', E'बौद्ध', E'हिन्दु', E'वैष्णव', 'A', E'किराँतहरूको धर्मगुरुको नाम मुयुहाङ हो।\nकोशी नदीको लगभग बीच भागमा अवस्थित किराँत जातिको ऐतिहासिक धार्मिक महत्व रहेको पवित्र इङ्गुलोको नाम बुधासुभो हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 8, E'उपयुक्त जोडा छुनोट गर्नुहोस्।\n१. आर्थिक सर्वेक्षण २०८१/८२ अनुसार २०८१ फागुनसम्म विद्युतमा पहुँच पुगेको जनसङ्ख्या ९९.०% रहेको छ।\n२. आर्थिक सर्वेक्षण २०८१/८२ अनुसार २०८१ फागुन सम्म नेपाल सरकारले पूर्ण तथा अधिकांश स्वामित्व भएका वाणिज्यिक बैंकको संख्या ४२ वटा रहेको छ।\n३. आ.व. २०८१/८२ को कुल गार्हस्थ उत्पादनमा बैंक तथा वित्तीय क्षेत्रको योगदान ६.२९% रहेको छ।', E'१ र ३ मात्र सही', E'२ र ३ मात्र सही', E'१, २ र ३ सबै सही', E'१, २ र ३ सबै गलत', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 9, E'१६औं पञ्चवर्षीय योजनाको अनुमानित आर्थिक वृद्धिदर कति अनुमान गरिएको थियो ?', E'७.३ प्रतिशत', E'५.९ प्रतिशत', E'१.५ प्रतिशत', E'९ प्रतिशत', 'A', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 10, E'वातावरणीय पुरस्कार सम्बन्धी गलत भनाई छुनोट गर्नुहोस्।', E'Blue Planet Prize - वातावरण क्षेत्रको सबैभन्दा धेरै रकम राशी भएको पुरस्कार', E'Goldman पुरस्कार - वातावरण क्षेत्रको नोवेल पुरस्कार (Green Nobel Prize)', E'Global-५०० - संयुक्त राष्ट्रसङ्घीय वातावरण कार्यक्रम (UNEP) द्वारा स्थापित', E'Gallente Conservation Award - वातावरण क्षेत्रको काँस्के पुरस्कार', 'D', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 11, E'विश्वमा वातावरण सम्बन्धमा निर्णय गर्ने उच्चस्तरको निकाय कुन हो ?', E'UN Environment Assembly', E'UN Conference on Sustainable Development', E'UN General Assembly', E'UN Security Council', 'A', E'संयुक्त राष्ट्रसङ्घीय वातावरण कार्यक्रम (UNEP) को स्थापना सन् १९७२ जुन ५ मा भएको हो।\nविश्व वातावरण दिवस जुन ५ मा मनाइन्छ।', 'nepali', true, NULL, NULL),
