      (v_set_id, 13, E'सार्कको ४८ औं शिखर सम्मेलन द्वारा स्थापित अन्तिम सार्क क्षेत्रीय केन्द्र कुन हो ?', E'सार्क ऊर्जा केन्द्र', E'सार्क प्रकोप व्यवस्थापन केन्द्र', E'सार्क विपद केन्द्र', E'सार्क वन केन्द्र', 'B', E'सार्कको पहिलो महासचिव अबुल अहसन हुन्।', 'nepali', true, NULL, NULL),
      (v_set_id, 14, E'सन् २०२५ डिसेम्बरमा घोषित फिफा वर्ष उत्कृष्ट प्रशिक्षक (पुरुष) को हुन् ?', E'लुइस एनरिक', E'हान्सी फ्ल्याम्पार्ड', E'जियानलुइजी डोनाल्म्मा', E'लिजवेकि ओभाला', 'A', E'', 'nepali', true, NULL, NULL),
