      (v_set_id, 11, E'सही जोडा मिलाई विकल्प छान्नुहोस् :\n(१) विश्व जनसङ्ख्या दिवस   क. अप्रिल २२\n(२) पृथ्वी दिवस   ख. सेप्टेम्बर १६\n(३) ओजोन तह सरक्षण अन्तर्राष्ट्रिय दिवस   ग. जुलाई ११\n(४) विश्व बाघ दिवस   घ. जुलाई २९', E'१-क, २-ख, ३-ग, ४-घ', E'१-ख, २-ग, ३-घ, ४-क', E'१-ग, २-क, ३-ख, ४-घ', E'१-घ, २-क, ३-ख, ४-ग', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 12, E'सार्कको बडाएसमा कति धारा रहेका छन् ?', E'१०', E'११', E'१२', E'१३', 'A', E'सार्कको प्रतीक चिन्ह डिजाइन गर्ने नेपाली कलाकार शैलेन्द्र कुमार महर्जन हुन्।\nसार्क सचिवालय काठमाडौँ, नेपाल मा स्थापना गरिएको छ।', 'nepali', true, NULL, NULL),
      (v_set_id, 13, E'सार्कको अध्यक्षता कति वर्षमा परिवर्तन हुन्छ ?', E'प्रत्येक वर्ष', E'२ वर्षमा', E'३ वर्षमा', E'४ वर्षमा', 'B', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 14, E'विश्व भोकमरी सूचकाङ्क (ग्लोबल हङ्गर इन्डेक्स-जिएचआई) २०२५ मा नेपाल कति स्थानमा रहेको छ ?', E'६२ औँ', E'७२ औँ', E'८२ औँ', E'९२ औँ', 'B', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 15, E'रुसका राष्ट्रपति भ्लादिमिर पुटिनद्वारा भारतको औपचारिक भ्रमण कहिले भएको हो ?', E'सन् २०२५ अप्रिल ४-५', E'सन् २०२५ अगस्ट ४-५', E'सन् २०२५ डिसेम्बर ४-५', E'सन् २०२५ मे ४-५', 'C', E'', 'nepali', true, NULL, NULL),
