    VALUES
      (v_set_id, 1, E'पृथ्वीले सूर्यलाई परिक्रमा गर्ने गति कति छ ?', E'१० कि.मि. प्रति सेकेण्ड', E'२० कि.मि. प्रति सेकेण्ड', E'३० कि.मि. प्रति सेकेण्ड', E'४० कि.मि. प्रति सेकेण्ड', 'D', E'आफ्नो अक्षको वरिपरि घुम्दा पृथ्वीको गति भूमध्यरेखामा प्रति घण्टा १६०० कि.मि. हुन्छ। आफ्नो अक्षको वरिपरि घुम्दा गति ध्रुवमा शून्य हुन्छ।', 'nepali', true, NULL, NULL),
