    VALUES
      (v_set_id, 1, E'उत्तरी ध्रुवको माथि निरन्तर र अटल रूपमा देखिने तारा कुन हो ?', E'ध्रुवतारा', E'पिण्ड', E'उल्कापात', E'पुच्छ्रेतारा', 'D', E'भूमध्येखुको बनावट ग्यासीय वरफको डल्लोको रूपमा रहेको हुन्छ।', 'nepali', true, NULL, NULL),
      (v_set_id, 2, E'विश्वको सबैभन्दा लामो नदी कुन हो ?', E'अमेजन', E'मिसिसिपी', E'ब्रह्मपुत्र', E'नाईल', 'D', E'एसियाको सबैभन्दा लामो नदी याङ्के । नाइल नदी १० देश भएर बग्दछ।', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'देहायमध्ये कुन भनाई गलत छ ?', E'महासागरको गहिराई मापन गर्ने यन्त्रलाई Fathometer भनिन्छ।', E'बर्मुडा त्रिकोण प्रशान्त महासागरमा पर्दछ।', E'ग्रिनल्याण्ड टापु आर्थर महासागरमा पर्दछ।', E'नाइल नदी भूमध्य सागरमा गएर अन्त्य हुन्छ।', 'D', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'क्षेत्रफलको आधारमा विश्वको दोस्रो ठूलो महासागर आन्ध्र महासागर पर्दछ ?', E'लेउप्ये पिक', E'कुन हिमश्रृङ्खला अन्तर्गत पर्दछ ?', E'मकालु', E'खुम्बु', 'A', E'', 'nepali', true, NULL, NULL),
