    VALUES
      (v_set_id, 1, E'सौर्यमण्डलमा बुध ग्रहभन्दा टाढा उपग्रहहरू कति ओटा छन् ?', E'२ (गेनेमेड र टाइटन)', E'२ (गेनेमेड र डेमोस)', E'३ (फेमोस गेनिमेड र टाइटन)', E'२ (फेमोस गेनिमेड)', 'A', E'पहिलो मानव निर्मित उपग्रह स्पुतनिक १ हो।\nसोभियत रुसले स्पुतनिक १ सन् १९५७ अक्टोबर ४ मा अन्तरिक्षमा पठाएको हो।\nस्पुतनिक २ सर्वप्रथम अन्तरिक्षमा पठाइएको प्राणी (कुकुर) को नाम लाइका हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 2, E'एसियाको भूपरिवेष्टित देश कुन हो ?', E'तुर्केमिनिस्तान', E'अफगानिस्तान', E'उज्बेकिस्तान', E'काजकिस्तान', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'पृथ्वीको सबैभन्दा गर्मी हुने स्थान कुन हो ?', E'अजिजिया (लिबिया)', E'डेथ भ्याली (क्यालिफोर्निया)', E'जकोबावाद (पाकिस्तान)', E'नेपालगन्ज (बाँके)', 'B', E'सबैभन्दा बढी ओसत वर्षा हुने स्थान: चेरापुन्जी', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'क्षेत्रफलको आधारमा महानगरपालिकाहरूको ठूलोबाट सानोको सही क्रम रोज्नुहोस्।', E'पोखरा, विराटनगर, वीरगन्ज, भरतपुर', E'भरतपुर, पोखरा, वीरगन्ज, विराटनगर', E'विराटनगर, वीरगन्ज, भरतपुर', E'पोखरा, भरतपुर, वीरगन्ज, विराटनगर', 'A', E'नेपालमा नगरपालिका विहिन जिल्ला ५ र गाउँपालिका विहिन जिल्ला ७ वटा रहेका छन्।', 'nepali', true, NULL, NULL),
