      (v_set_id, 11, E'नेपालले कहिले सम्ममा कार्बन तटस्थताको शुन्यमा फार्ने लक्ष्य राखेको छ ?', E'सन् २०२५', E'सन् २०३०', E'सन् २०४५', E'सन् २०५०', 'C', E'क्लाइमेट इमर्जेन्सी (Climate Emergency) घोषणा गर्ने पहिलो देश बेलायत हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 12, E'विमस्टेकको सातौं सम्मेलन २०२९ मा कुन देशमा आयोजना हुँदैछ ?', E'भारत', E'थाइल्याण्ड', E'बंगलादेश', E'नेपाल', 'C', E'विमस्टेकको हालको अध्यक्ष राष्ट्र थाइल्याण्ड हो। विमस्टेकमा आपसी सहयोगको क्षेत्रफल ७वटा रहेका छन्। विमस्टेकको महासचिवको कार्यकाल ३ वर्ष अवधिको हुन्छ।', 'nepali', true, NULL, NULL),
      (v_set_id, 13, E'नेपाल र युरोपियन यूनियन बीच ............... मा कूटनैतिक सम्बन्ध कायम भएको हो ?', E'सन्१९७३', E'सन्१९७४', E'सन्१९७५', E'सन्१९७६', 'B', E'', 'nepali', true, NULL, NULL),
