      (v_set_id, 22, E'''''पहिले सिकेको कुराहरू स्थायी वा अस्थायी रूपमा चिन्ने वा प्रत्याहान गर्ने क्षमता हास आउनुलाई विस्मरण भनिन्छ।'''' यो भनाइ कसको हो?', E'डेभर', E'भटिया', E'प्लेटो', E'थर्नडाइक', 'B', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 23, E'शिक्षकको माध्यमबाट विषयप्रस्तुति सिकारुले हासिल गरेको ज्ञान लाई उपयुक्त परिवेश र परिस्थितिमा स्थान्तरण गर्दा कुन तत्वको प्रभाव हुँदैन ?', E'शिक्षकको क्षमता', E'सिकारुको क्षमता', E'सिकारुको उच्च र आवश्यकता', E'सामाजिकता गर्ने क्षमता', 'A', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 24, E'तिख्ण बुद्धिका विद्यार्थीको तुलनामा मन्द बुद्धिका विद्यार्थीले ढिलो सिक्दछन् भन्ने अवधारणा सिकाइ स्थान्तरणको कुन सिद्धान्तसँग सम्बन्धित छ ?', E'स्थान्तरणको सिद्धान्त', E'मानसिक अनुशासनको सिद्धान्त', E'सामान्यीकरणको सिद्धान्त', E'आदर्श सिद्धान्त', 'B', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 25, E'राष्ट्रिय पाठ्यक्रम प्रारूप, २०७६ मा भएको व्यवस्था अनुसार कक्षा ८ सम्मको स्थानीय पाठ्यक्रम तथा पाठ्य सामग्री कसले बनाउन पाउने अधिकार रहेको छ ?', E'सङ्घले', E'प्रदेशले', E'स्थानीय तहले', E'माथिका सबैले', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 26, E'बाल मनोविज्ञान, सिकाइको आधार र मानव विकासको स्तरको आधारमा विद्यालय शिक्षा को तहगत र कक्षागत सिकाइ क्षमता स्तर कति तहमा विभाजन गरिएको छ ?', E'२', E'३', E'४', E'५', 'D', E'', 'nepali', true, NULL, NULL),
