      (v_set_id, 45, E'आधारभूत तथा माध्यमिक तहसम्मको शिक्षा निःशुल्क व्यवस्थापन गर्ने जिम्मेवारी कसको हो ?', E'शिक्षा तथा मानव श्रोत विकास केन्द्र', E'गाउँपालिका वा नगरपालिका', E'शिक्षा विकास तथा समन्वय इकाई', E'वडा समिति', 'B', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 46, E'हरिले ३ वटा झोलाहरू रू. ६४५ मा बेच्दा रू ५१ नोक्सान भयो भने प्रति झोला कतिको दरमा किनेको होला?', E'२३२', E'२६८', E'२४५', E'२५२', 'A', E'', 'nepali', true, NULL, NULL),
