      (v_set_id, 2, E'प्रद्विहरूको पनि प्रद्विहरू भनेर कुन महादेशलाई चिनिन्छ ?', E'अफ्रिका', E'युरोप', E'उत्तर अमेरिका', E'अस्ट्रेलिया', 'B', E'पूरै उत्तरी गोलार्द्धमा अवस्थित महादेश युरोप हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'एसिया महादेशमा कति वटा भूपरिवेष्टित राष्ट्र छन् ?', E'१०', E'११', E'१२', E'१६', 'C', E'अफ्रिकी महादेशमा १६ वटा भूपरिवेष्टित राष्ट्र छन्। सबैभन्दा धेरै भूपरिवेष्टित देश भएको महादेश अफ्रिका हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'''बोधीसत्व'' कुन जिल्लामा उत्पादन हुन्छ ?', E'काप्रेपलान्चोक', E'रामेछाप', E'दोलखा', E'सिन्धुपाल्चोक', 'A', E'Yellow Living Gold भनेर यार्शागुम्बा लाई चिनिन्छ।\nगण्डकको मानव नदीहरू: निशुली, बुढीगण्डकी, दरौदी, मर्स्याङ्दी, सेती गण्डकी, काली गण्डकी, मादी', 'nepali', true, NULL, NULL),
