      (v_set_id, 11, E'हरितगृह ग्याँसको उत्सर्जन घटाउन र ओजन तहको क्षयीकरणलाई रोक्नका लागि विश्वका १४१ राष्ट्रले अनुमोदन गरी हस्ताक्षर गरेको साझा प्रोटोकोल कुन भनिन्छ?', E'क्योटो प्रोटोकल', E'भियना प्रोटोकल', E'हेग घोषणा', E'बर्लिन प्रोटोकल', 'A', E'सन् १९९७ डिसेम्बर ११ मा जापानको क्योटो सहरमा हस्ताक्षरित क्योटो प्रोटोकल सन् २००५ फेब्रुअरी १६ देखी लागू भएको थियो।', 'nepali', true, NULL, NULL),
      (v_set_id, 12, E'बिम्सटेक सँग सम्बन्धमा कुन तथ्य मेल खाँदैन ?', E'BIMSTEC Charter मा ३० वटा धाराहरू (Articles) छन्।', E'BIMSTEC Charter मा सन् २०२२ मार्च ३० मा ५ औं शिखर सम्मेलनमा हस्ताक्षर भएको हो।', E'BIMSTEC Secretariat मा सन् २०१४ मा हस्ताक्षर भएको हो।', E'BIMSTEC मा नेपालको तर्फबाट तत्कालिन प्रधानमन्त्री शेर बहादुर देउवालले हस्ताक्षर भएको छ।', 'A', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 13, E'संयुक्त राष्ट्र सङ्घको बढापत्रमा हस्ताक्षर कहिले भएको थियो ?', E'१९४२ जनवरी १', E'१९४५ अप्रिल २५', E'१९४५ जुन २६', E'१९४६ अक्टोबर २४', 'C', E'संयुक्त राष्ट्र सङ्घको बढापत्रमा ५१ ओटा संस्थापक मुलुकले हस्ताक्षर गरेका छन्।', 'nepali', true, NULL, NULL),
      (v_set_id, 14, E'संयुक्त राष्ट्र सङ्घ सुरक्षा परिषद्को अस्थायी सदस्य राष्ट्रहरूमध्ये सन् २०२६ डिसेम्बरमा कार्यकाल समाप्त हुने राष्ट्र कुन हो ?', E'दक्षिण कोरिया', E'गुयना', E'डेनमार्क', E'अल्जेरिया', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 15, E'आर्थिक सर्वेक्षण २०८१/०८२ अनुसार नेपालमा उद्योगहरू बढी लगानी देश (संस्था) को आधार क्रम कुन दिन ठीक छ?', E'चीन, भारत, दक्षिण कोरिया, जापान र बेलायत', E'चीन, भारत, अमेरिका, दक्षिण कोरिया र बेलायत', E'चीन, भारत, दक्षिण कोरिया र बेलायत', E'चीन, भारत, अमेरिका, दक्षिण कोरिया र बेलायत', 'B', E'हाल नेपालमा ९९ प्रतिशत जनसङ्ख्यामा विद्युतको पहुँच (वैकल्पिक ऊर्जासहित) पुगेको छ', 'nepali', true, NULL, NULL),
      (v_set_id, 16, E'सबैका लागि शिक्षा राष्ट्रिय कार्ययोजना नेपाल (२००१-२०१५) ले कतिवटा लक्ष्यहरू निर्धारण गरेको छ?', E'५', E'६', E'७', E'९', 'C', E'लक्ष्यहरू छोटकरीमा:\n१. प्राथमिक बाल विकास शिक्षाका कार्यक्रमहरू वृत्तिविस्तीर्णन गर्ने\n२. नि:शुल्क तथा अनिवार्य प्राथमिक शिक्षाको पहुँच सुनिश्चित गर्ने\n३. न्यायपूर्ण पहुँच विस्तार गरी सुनिश्चित गराउने\n४. सन् २०१५ सम्म प्रौढ साक्षरता तहमा खासगरी महिला साक्षरतामा कम्तीमा ५०% वृद्धि गर्ने\n५. लैङ्गिक विभेदीकरण निर्मूल, लैङ्गिक समानता कायम गर्ने\n६. साक्षरता, गणितीय ज्ञान र जीवन उपयोगी सिपहरूको विकास सुनिश्चित गर्ने\n७. मातृभाषामा आधारभूत तथा प्राथमिक शिक्षा प्राप्त गर्न पाउने अधिकार सुनिश्चित गर्ने (नेपालले थप गरेको उद्देश्य)', 'nepali', true, NULL, NULL),
