      (v_set_id, 6, E'नेपाली इतिहासमा प्रामाणिक इतिहास कुन काल देखि लागू भएको देखिन्छ ?', E'किरातकाल', E'लिच्छविकाल', E'मल्लकाल', E'सोमवंशकाल', 'B', E'नेपालको पहिलो प्रमाणिक राजा मानदेव लाई मानिन्छ। लिच्छविकालका मानदेव को शासन वि.सं. ४२९ देखि लागू भएको मानिन्छ।', 'nepali', true, NULL, NULL),
      (v_set_id, 7, E'हाल नेपालको अर्थतन्त्रमा कुल गार्हस्थ्य उत्पादनमा बिशेषमा मध्य सबैभन्दा बढी योगदान दिने क्षेत्र को हो ?', E'कृषि', E'उद्योग', E'व्यापार', E'निर्माण क्षेत्र', 'A', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 8, E'सही जोडा मिलाउनुहोस् :\nपर्व\n(a) कोतपर्व\n(b) मकैको खेती\n(c) भण्डारखाल\n(d) अली\nव्यक्ति\n(i) चन्द्र शमशेर\n(ii) रानी राज्यलक्ष्मी\n(iii) राजा राजेन्द्र\n(iv) विरेन्द्रज वस्तुपाल', E'a-iii, b-ii, c-iv, d-i', E'a-i, b-ii, c-iv, d-iii', E'a-iii, b-ii, c-i, d-iv', E'a-ii, b-iii, c-iv, d-i', 'B', E'लाइब्रेरी पर्व नामक घटना वि.सं ११२० मा घटेको थियो । येती हुने राजा त्रिभुवन थिए ।', 'nepali', true, NULL, NULL),
