      (v_set_id, 48, E'Complete the given series: A, D, H, M, ?, Z', E'A Q', E'B S', E'C B', E'D N', 'B', E'', 'english', true, NULL, NULL),
      (v_set_id, 49, E'कुनै काम गर्न A लाई १२ दिन र B लाई १५ दिन लाग्छ । दुवैजना मिलेर रू. ४५० मा काम पूरा गर्ने जिम्मा लिनुभन्ने भने उक्त कामको कति हिस्सा A को भागमा आउँछ ?', E'रू. २००', E'रू. २५०', E'रू. ३००', E'रू. २४०', 'B', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 50, E'हरिले एउटा सामान रू. ३५५० मा बेच्दा रू. ४६० नोक्सान भएछ भने नोक्सान प्रतिशत पत्ता लगाउनुहोस् ।', E'११.५%', E'१३.५%', E'१२%', E'११%', 'A', E'', 'nepali', true, NULL, NULL)
    RETURNING id, order_number
