      (v_set_id, 2, E'समूह I र समूह II बीच जोडा मिलाउनुहोस् र कोडबाट सही उत्तर छान्नुहोस् ।\na. डेय्र\nb. सुपीरियर\nc. हिमालय पर्वतमाला\nd. लापाग (बोलिभिया)\n1. अन्तरराष्ट्रिय नदी\n2. विश्वको ठूलो स्वच्छ पानीको ताल\n3. विश्वको अग्लो स्थानको पर्वतमाला\n4. विश्वको अग्लो स्थानको राजधानी', E'a4, b1, c2, d3', E'a3, b1, c2, d4', E'a3, b1, c2, d4', E'a2, b1, c4, d3', 'D', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'कुन अक्षांश रेखा माथि सूर्यको प्रकाश सिधा पर्न दिन र रातको लम्बाइ बराबर हुन्छ ?', E'भूमध्य रेखा', E'कर्कट रेखा', E'मकर रेखा', E'घोडे अक्षांश', 'A', E'भूमध्यरेखा माथि सूर्यको प्रकाश एक वर्षमा २ पटक सिधा पर्दछ ।', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'देहायका मध्ये कुन भनाई गलत छ ?', E'नेपालका गाउँपालिका बिहीन जिल्ला इलोवेज रहेका छन्।', E'कस्तरीय दुई वटा प्रदेश कर्णाली र सुदुरपश्चिममा गाउँपालिकाको सङ्ख्या बराबर छन्।', E'क्षेत्रफल बराबर भएको गाउँपालिका चम्पादेवी र चिशङ्खुगढी (खोटाङ्ग) हुन्।', E'B', 'D', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 5, E'सही जोडा मिलाउनुहोस् :\n(a) कोशी नदी\n(b) गण्डकी/नारायणी नदी\n(c) कर्णाली नदी\n(d) अग्राहर\n(i) ठूलो नदी\n(ii) छोटो नदी\n(iii) लामो नदी\n(iv) गहिरो नदी', E'a-i, b-ii, c-iii, d-iv', E'a-ii, b-i, c-iii, d-iv', E'a-iii, b-iv, c-i, d-ii', E'a-iv, b-ii, c-iii, d-i', 'D', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 6, E'निल्छविकालमा कृषि उत्पादनमा लगाउने करलाई के भनिन्छ ?', E'सिंकर', E'भाग', E'कर', E'अग्राहर', 'B', E'', 'nepali', true, NULL, NULL),
