      (v_set_id, 12, E'सार्कको पहिलो क्षेत्रिय केन्द्र कुन हो ?', E'सार्क सूचना केन्द्र', E'सार्क कृषि सूचना केन्द्र', E'सार्क क्षयरोग केन्द्र', E'सार्क ऊर्जा केन्द्र', 'B', E'सार्क साहित्य पुरस्कार दुई पटक प्राप्त गर्ने नेपाली साहित्यकार युमन पोखरेल हुन ।', 'nepali', true, NULL, NULL),
      (v_set_id, 13, E'बिम्स्टेकको झण्डाको पृष्ठभूमिमा कुन रङको प्रयोग भएको छ ?', E'सेतो', E'रातो', E'पहेलो', E'निलो', 'A', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 14, E'विचार गर्नुहोस् (राष्ट्रिय आर्थिक गणना, २०८२ सम्बन्धमा)\n१. गणना २०८२ चैत्र १ गतेदेखि गरिने,\n२. नारा: अर्थतन्त्र मापनको लागि आर्थिक गणना रहेको,\n३. २०८२ पुस २२ गते लोगो र नारा सार्वजनिक गरिएको ।', E'१ र ३ सही २ गलत', E'सबै सही', E'सबै गलत', E'१ र २ सही ३ गलत', 'D', E'', 'nepali', true, NULL, NULL),
