  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- Surface in the topic list (unlocked — mock exams are not a gated sequence)
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;
  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% Qs)', E'निमावि प्रथम पत्र — मोडेल सेट २३', 50;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- निमावि प्रथम पत्र — मोडेल सेट २४  (50 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id  uuid;
  v_set_id    uuid;
  v_existing  uuid;
  v_next_step int;
BEGIN
  SELECT t.id INTO v_topic_id
  FROM public.topics t
  JOIN public.subjects s ON s.id = t.subject_id
  JOIN public.modules  m ON m.id = s.module_id
  WHERE m.slug = 'nimavi-pratham-patra' AND s.slug = 'abhyas' AND t.slug = 'model-set'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'Topic % not found (scaffold block must run first)', 'model-set';
  END IF;

  SELECT id INTO v_existing FROM public.question_sets
  WHERE title = E'निमावि प्रथम पत्र — मोडेल सेट २४' AND topic_id = v_topic_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'निमावि प्रथम पत्र — मोडेल सेट २४';
    RETURN;
  END IF;

  INSERT INTO public.question_sets (topic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, E'निमावि प्रथम पत्र — मोडेल सेट २४', 2, 'mock_exam', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d,
       correct_option, explanation, language, is_verified, exam_year, paper_ref)
    VALUES
      (v_set_id, 1, E'भित्रि ग्रह (Inner planet) मा कुन ग्रह पर्दैन ?', E'बुध, शुक्र, पृथ्वी र वरुण', E'बुध, शुक्र, पृथ्वी र शनि', E'बुध, शुक्र, पृथ्वी र बृहस्पति', E'बुध, शुक्र, पृथ्वी र मङ्गल', 'D', E'माहिरी ग्रह (Outer Planet/Jovian Planets) मा बृहस्पति, शनि, वरुण र मरुण ग्रह पर्दछन्।', 'nepali', true, NULL, NULL),
      (v_set_id, 2, E'निम्नलिखित जोडाहरू मिलान गर्नुहोस्।\nमहादेश (Continent)\tविशेषता (Characteristics)\n१) युरोप\ta. विविधताको महादेश\n२) अफ्रिका\tb. सक्रिय ज्वालामुखी विहीन\n३) अष्ट्रेलिया\tc. मरुभूमि विहीन\n४) अन्टार्कटिका\td. मरुभूमि विहीन', E'१-a, २-d, ३-c, ४-b', E'१-b, २-c, ३-a, ४-d', E'१-d, २-a, ३-b, ४-c', E'१-b, २-d, ३-c, ४-a', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'विश्वको सबैभन्दा गर्मी हुने स्थान डेथभ्याली (Death Valley) कुन देशमा पर्दछ ?', E'दक्षिण अफ्रिका', E'अष्ट्रेलिया', E'संयुक्त राज्य अमेरिका', E'ईटाली', 'C', E'सबैभन्दा बढी देशसँग सिमाना जोडिएको देश: चिन', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'नेपालले एसिया महादेशको कति प्रतिशत भूभाग ओगटेको छ ?', E'३.०२', E'२.५२', E'२.३२', E'१.३२', 'B', E'नेपालको उत्तर दक्षिण औसत चौडाइ १९३ कि.मि. रहेको छ।\nनेपालको पूर्व पश्चिम लम्बाइ ८८५ कि.मि. रहेको छ।', 'nepali', true, NULL, NULL),
