-- ─────────────────────────────────────────────────────────────────────
-- निमावि प्रथम पत्र — मोडेल सेट २८  (50 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id  uuid;
  v_set_id    uuid;
  v_existing  uuid;
  v_next_step int;
BEGIN
  SELECT t.id INTO v_topic_id
  FROM public.topics t
  JOIN public.subjects s ON s.id = t.subject_id
  JOIN public.modules  m ON m.id = s.module_id
  WHERE m.slug = 'nimavi-pratham-patra' AND s.slug = 'abhyas' AND t.slug = 'model-set'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'Topic % not found (scaffold block must run first)', 'model-set';
  END IF;

  SELECT id INTO v_existing FROM public.question_sets
  WHERE title = E'निमावि प्रथम पत्र — मोडेल सेट २८' AND topic_id = v_topic_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'निमावि प्रथम पत्र — मोडेल सेट २८';
    RETURN;
  END IF;

  INSERT INTO public.question_sets (topic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, E'निमावि प्रथम पत्र — मोडेल सेट २८', 2, 'mock_exam', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d,
       correct_option, explanation, language, is_verified, exam_year, paper_ref)
    VALUES
      (v_set_id, 1, E'एकापट्टि तातो र अर्कोपट्टि चिसो हुने ग्रह कुन हो ?', E'बुध', E'शुक्र', E'मङ्गल', E'वरुण', 'A', E'(सबै एकटा भाग सुर्यतिर फर्किरहने, सूर्यका सबैभन्दा नजिकको, सबैभन्दा छोटो समयमा सूर्यको परिक्रमा गर्ने ग्रह : बुध)\n(शुक्रलाई Morning Star, Evening Star, Goddess of Love and Beauty, रहस्यमय ग्रह, पृथ्वीबाट अनुसन्धान गरिएको पहिलो ग्रह)', 'nepali', true, NULL, NULL),
