-- ─────────────────────────────────────────────────────────────────────
-- निमावि प्रथम पत्र — मोडेल सेट ३२  (50 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id  uuid;
  v_set_id    uuid;
  v_existing  uuid;
  v_next_step int;
BEGIN
  SELECT t.id INTO v_topic_id
  FROM public.topics t
  JOIN public.subjects s ON s.id = t.subject_id
  JOIN public.modules  m ON m.id = s.module_id
  WHERE m.slug = 'nimavi-pratham-patra' AND s.slug = 'abhyas' AND t.slug = 'model-set'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'Topic % not found (scaffold block must run first)', 'model-set';
  END IF;

  SELECT id INTO v_existing FROM public.question_sets
  WHERE title = E'निमावि प्रथम पत्र — मोडेल सेट ३२' AND topic_id = v_topic_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'निमावि प्रथम पत्र — मोडेल सेट ३२';
    RETURN;
  END IF;

  INSERT INTO public.question_sets (topic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, E'निमावि प्रथम पत्र — मोडेल सेट ३२', 2, 'mock_exam', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d,
       correct_option, explanation, language, is_verified, exam_year, paper_ref)
    VALUES
      (v_set_id, 1, E'उपयुक्त जोडा छनोट गर्नुहोस् ।\nA. जोहन गा\nB. विलियम हर्सेल\nC. ग्यालिलियो\ni. शनि\nii. वरुण\niii. वर्षीं\niv. मङ्गल', E'a-ii, b-iii, c-i', E'a-i, b-iii, c-iv', E'a-iii, b-i, c-iv', E'a-iii, b-i, c-iv', 'A', E'(टिडयुक्त ग्रह, औंस घनत्व सबैभन्दा कम भएको ग्रह, Yellow Planet सुन्दर- शनि)', 'nepali', false, NULL, NULL),
      (v_set_id, 2, E'पृथ्वीले सूर्यको परिक्रमा गर्दा कति डिग्रीको कोणमा भुक्केको हुन्छ ?', E'२०.५°', E'२३.५°', E'६६.५°', E'९०.५°', 'B', E'प्रत्येक १६२ मिटरको उचाइमा १ डिग्री सेन्टीग्रेड तापक्रम घट्ने जान्छ ।', 'nepali', true, NULL, NULL),
