      (v_set_id, 2, E'विश्वको सबैभन्दा ठूलो उष्ण मरुभूमि कुन हो ?', E'गोबी', E'अरेबियन', E'सहारा', E'थार', 'C', E'एसिया महादेशको सबैभन्दा ठूलो जिस्रो मरुभूमि: गोबी, उष्ण मरुभूमि अरेबियन हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'चन्द्रमा तपाईंका तौल पृथ्वीको भन्दा कम हुन्छ किनभने ?', E'चन्द्रमा हावा छैन', E'चन्द्रमा पृथ्वी भन्दा सानो छ', E'चन्द्रमाको गुरुत्वाकर्षण पृथ्वीको भन्दा कमजोर छ', E'चन्द्रमा सूर्यको धेरै टाढा छ', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'समूह (I) र (II) बिच सही जोडा मिलाउनुहोस्।\nसमूह (I) राष्ट्रिय निकुञ्ज\nक. चितवन\nख. बर्दिया\nग. पर्सा\nघ. शुक्लाफाँटा\nसमूह (II) बाघ सङ्ख्या\n(अ) १२८\n(आ) १२५\n(इ) ४१\n(ई) ३६', E'क-अ, ख-आ, ग-इ, घ-ई', E'क-इ, ख-आ, ग-ई, घ-अ', E'क-आ, ख-अ, ग-इ, घ-ई', E'क-इ, ख-आ, ग-अ, घ-ई', 'C', E'शुक्लाफाँटा बञ्जरगुम आरक्ष कञ्चनपुर जिल्लामा रहेको छ।', 'nepali', true, NULL, NULL),
      (v_set_id, 5, E'कर्णाली प्रदेशका तलकामध्ये कुन स्रोत सबैभन्दा बढी पाइन्छ ?', E'जलस्रोत', E'प्राकृतिक ग्यास', E'कोइला', E'फलाम', 'C', E'शालिग्राम बञ्जनपुर विश्वको सबैभन्दा कालीगण्डकी नदी।\nनेपालको छालाका लागि प्रसिद्ध जिल्ला बैतडी हो।', 'nepali', false, NULL, NULL),
