      (v_set_id, 41, E'नेपालको संविधान २०७२ मा भएको व्यवस्था अनुसार प्रत्येक नेपाली नागरिकको कर्तव्य तलकामध्ये कुन हो ?', E'सार्वजनिक सम्पत्तिको सुरक्षा र संरक्षण गर्नु', E'राज्यले चाहेका बखत अनिवार्य सेवा गर्नु', E'संविधान र कानुनको पालना गर्नु', E'माथिका सबै', 'D', E'नेपाली नागरिकका कर्तव्य संविधानमा हुँदै नेपालको राष्ट्रिय हित कायम राख्नु र अखण्डताको रक्षा गर्नु', 'nepali', true, NULL, NULL),
      (v_set_id, 42, E'शिक्षा ऐन, २०२८(सशोधनसहित) अनुसार शिक्षक सेवा आयोगको अध्यक्ष र सदस्यको सिफारिस गर्न गठित समितिको अध्यक्ष को रहने व्यवस्था रहेको छ?', E'वि.वि.को उपकुलपति', E'शिक्षा सचिव', E'लोकसेवा आयोगको अध्यक्ष', E'शिक्षामन्त्री र निजले तोकेको व्यक्ति', 'C', E'(वि.वि.को उपकुलपति, शिक्षा सचिव सदस्य रहने)', 'nepali', true, NULL, NULL),
      (v_set_id, 43, E'राष्ट्रिय पाठ्यक्रम विकास तथा मूल्याङ्कन परिषदका काम देहायकामध्ये कुन होइन ?', E'थप पाठ्यसामग्री तथा पाठ्यपुस्तकको सूची स्वीकृत गर्ने', E'बहु पाठ्यपुस्तक स्वीकृत निर्धारण गर्ने तर्जुमा गरी नेपाल सरकार समक्ष पेश गर्ने', E'सामुदायिक विद्यालयमा लागु गरिने पाठ्यक्रम तथा पाठ्यपुस्तक निर्माण गर्ने नीति निर्धारण गर्ने', E'सामुदायिक विद्यालयमा लागु गरिने पाठ्यक्रम तथा पाठ्यपुस्तक निर्माण गर्ने', 'D', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 44, E'शिक्षक सेवा आयोगले कतैमा शिक्षक नियुक्ति गर्ने प्रयोजनका लागि सिफारिस गरिएका पद सङ्ख्या आधारमा माध्यमिक तहको विज्ञापन भएको पदको कति सङ्ख्यामा उम्मेदवारको योग्यताक्रम अनुसार प्रकाशन गर्नुपर्छ ?', E'विज्ञापन सङ्ख्या बराबर', E'विज्ञापन सङ्ख्याको दोब्बर', E'विज्ञापन सङ्ख्याको २५ प्रतिशत', E'विज्ञापन सङ्ख्याको आधा', 'B', E'(प्राथमिक तथा शतप्रतिशत निम्न माध्यमिक तथा शतप्रतिशत बढ्ी सङ्ख्याका करार सूची निकाल्नुपर्ने)', 'nepali', true, NULL, NULL),
