-- ─────────────────────────────────────────────────────────────────────
-- निमावि प्रथम पत्र — मोडेल सेट ३६  (50 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id  uuid;
  v_set_id    uuid;
  v_existing  uuid;
  v_next_step int;
BEGIN
  SELECT t.id INTO v_topic_id
  FROM public.topics t
  JOIN public.subjects s ON s.id = t.subject_id
  JOIN public.modules  m ON m.id = s.module_id
  WHERE m.slug = 'nimavi-pratham-patra' AND s.slug = 'abhyas' AND t.slug = 'model-set'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'Topic % not found (scaffold block must run first)', 'model-set';
  END IF;

  SELECT id INTO v_existing FROM public.question_sets
  WHERE title = E'निमावि प्रथम पत्र — मोडेल सेट ३६' AND topic_id = v_topic_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'निमावि प्रथम पत्र — मोडेल सेट ३६';
    RETURN;
  END IF;

  INSERT INTO public.question_sets (topic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, E'निमावि प्रथम पत्र — मोडेल सेट ३६', 2, 'mock_exam', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d,
       correct_option, explanation, language, is_verified, exam_year, paper_ref)
    VALUES
      (v_set_id, 1, E'निम्न सवालहरूबारे विचार गरी ठिक, बेठिक पहिचान गर्नुहोस्:\nA. विद्यालयमा उत्पत्ति लगभग साढे चार अर्ब वर्ष पहिले भएको हो\nB. पुड्डे ताराहरू आफ्नै प्रकाशले चम्किन्छन्\nC. सूर्यमा पाइने प्रमुख तत्व हाइड्रोजन र हेलियम हो', E'सबै ठिक', E'A बेठिक', E'B बेठिक', E'C बेठिक', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 2, E'महासागरको पिछलाई के भनिन्छ?', E'Ocean Floor', E'Ocean deep', E'Ocean Mantle', E'Oceanic Core', 'A', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'निम्न भनाइहरू मनन गर्नुहोस् र सही छनोट गर्नुहोस्:\n१. बैकाल ताल विश्वको सबैभन्दा गहिरो ताल हो।\n२. बैकाल ताल विश्व सम्पदा सूचीमा सूचीकृत छ।', E'१ ठीक, २ बेठिक', E'१ बेठिक, २ ठीक', E'१ र २ दुवै ठीक', E'१ र २ दुवै बेठिक', 'C', E'मानव निर्मित विश्वको ठूलो ताल ओवन फल्स उगण्डा मा पर्दछ। विश्वको सबैभन्दा ठूलो नुनिलो पानीको ताल क्यासियन हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'पृथ्वीको ऋतु परिवर्तन हुने कारण देहायका मध्ये कुन होइन?', E'पृथ्वीको अक्ष २३.५° मा झुक्नु', E'पृथ्वी धेरै हदसम्म गोलाकार हुनु', E'पृथ्वीको सूर्यको परिक्रमा गर्नु', E'पृथ्वी आफ्नो अक्षम पश्चिमबाट पूर्व घुम्नु', 'D', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 5, E'हिमालका सम्बन्धमा कुन भनाइ सही छ?\na. नेपालको सबैभन्दा ठूलो हिमाल चठोरोल्पा हिमाल हो।\nb. कन्चुपे हिमालको विश्वकै सर्व उच्चतम हिमाल हो।\nc. इम्जा हिमताल सोलुखुम्बु जिल्लामा पर्दछ।\nd. मनाङमा अवस्थित ठूलानी हिमताल नेपालको सबैभन्दा सानो हिमताल हो।', E'a बेठिक', E'b बेठिक', E'a र c मात्र ठीक', E'a, b र c ठीक d बेठिक', 'B', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 6, E'जनकपुर-जयनगर रेल सेवा कुन राणा प्रधानमन्त्रीको पालामा सुरुवात भएको हो?', E'चन्द्र शमशेर', E'जुद्ध शमशेर', E'देव शमशेर', E'धीर शमशेर', 'B', E'विद्यालय जुम्मिकाको स्थापना हुँदा नेपालको प्रधानमन्त्रीमा जुद्ध शमशेर थिए।\nनेपालमा कागजी नोटको प्रचलन जुद्ध शमशेरको पाला देखि शुरुवात भएको हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 7, E'देहाय मध्ये कुन भनाई गलत छ?', E'नेपालको इतिहासमा लौह युग भनेर गणेशमान सिंहलाई चिनिन्छ।', E'बमशाहदुर राणालाई मालिक मिनिस्टर भनिन्छ।', E'नेपालका ''सिल्भनको द भिन्ची'' भनेर गहेन्द्र शमशेर लाई चिनिन्छ।', E'टंक प्रसाद आचार्य लाई नेपालको जिउंदो शहिद भनिन्छ।', 'A', E'इन्द्रजात्रामा लिङ्गो गाड्ने पटन भनाव सिंह शाहले चलाएका हुन्। इन्द्रजात्रामा कुमारीको रथ पृथक चलन जयप्रकाश मल्लले चलाएका हुन्। इन्द्रजात्रामा चलन प्रृथकमध्येबाट सुरु गरेका हुन्।', 'nepali', true, NULL, NULL),
      (v_set_id, 8, E'पञ्च करोड रूपैयाभन्दा बढी स्थिर जेथा भएको उद्योगहरूलाई कस्तो उद्योग भनिन्छ?', E'मझौला उद्योग', E'ठूला उद्योग', E'साना उद्योग', E'कुनै पनि होइनन्', 'C', E'', 'nepali', true, NULL, NULL),
