      (v_set_id, 4, E'सानो नेपाल भनेर कुन जिल्ला कुन हो?', E'भक्तपुर', E'बैतडी', E'बागलुङ्', E'दार्चुला', 'A', E'शिवालिक पर्वत, बाह्य हिमालय र दक्षिण हिमालय भन्ने पर्वत श्रेणीलाई चिनिन्छ।', 'nepali', true, NULL, NULL),
      (v_set_id, 5, E'सही जोडा मिलाउनुहोस्। नेपालमा:\nक. क्षेत्रफलका आधारमा सबैभन्दा ठूलो प्रदेश\nख. क्षेत्रफलका आधारमा सबैभन्दा सानो प्रदेश\nग. साक्षरता दर बढी भएको प्रदेश\nघ. जिल्ला सङ्ख्या बढी भएको प्रदेश\n१) बागमती प्रदेश\n२) कोशी प्रदेश\n३) कर्णाली प्रदेश\n४) मधेस प्रदेश', E'क-४, ख-३, ग-२, घ-१', E'क-२, ख-१, ग-४, घ-३', E'क-३, ख-४, ग-१, घ-२', E'क-३, ख-२, ग-१, घ-४', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 6, E'नेपालको दौत्य सम्बन्धमा कुन भनाई सही छ?\n१. अफ्रिकी महादेशबाट नेपालको दौत्य सम्बन्ध पहिलो भएको देश इजिप्ट हो।\n२. दक्षिण अमेरिकी महादेशबाट नेपालको दौत्य सम्बन्ध पहिलो भएको देश ब्राजिल हो।', E'१ र २ दुवै ठीक', E'१ र २ दुवै गलत', E'१ ठीक र २ गलत', E'२ ठीक १ गलत', 'D', E'', 'nepali', true, NULL, NULL),
