-- ─────────────────────────────────────────────────────────────────────
-- निमावि प्रथम पत्र — मोडेल सेट ३८  (50 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id  uuid;
  v_set_id    uuid;
  v_existing  uuid;
  v_next_step int;
BEGIN
  SELECT t.id INTO v_topic_id
  FROM public.topics t
  JOIN public.subjects s ON s.id = t.subject_id
  JOIN public.modules  m ON m.id = s.module_id
  WHERE m.slug = 'nimavi-pratham-patra' AND s.slug = 'abhyas' AND t.slug = 'model-set'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'Topic % not found (scaffold block must run first)', 'model-set';
  END IF;

  SELECT id INTO v_existing FROM public.question_sets
  WHERE title = E'निमावि प्रथम पत्र — मोडेल सेट ३८' AND topic_id = v_topic_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'निमावि प्रथम पत्र — मोडेल सेट ३८';
    RETURN;
  END IF;

  INSERT INTO public.question_sets (topic_id, title, difficulty_level, set_type, is_verified)
  VALUES (v_topic_id, E'निमावि प्रथम पत्र — मोडेल सेट ३८', 2, 'mock_exam', true)
  RETURNING id INTO v_set_id;

  WITH ins AS (
    INSERT INTO public.questions
      (set_id, order_number, content, option_a, option_b, option_c, option_d,
       correct_option, explanation, language, is_verified, exam_year, paper_ref)
    VALUES
      (v_set_id, 1, E'सप्तऋषि तारा समूहलाई अङ्ग्रेजी भाषामा के भनिन्छ ?', E'Milky Way', E'Great Tiger', E'Great Bear', E'Septinal', 'C', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 2, E'उत्तरी ध्रुवदेखि दक्षिणी ध्रुवसम्म फैलिएको ठूलो महासागर कुन हो ?', E'प्रशान्त', E'आन्ध्र', E'हिन्द', E'सुमेरु', 'B', E'आन्ध्र महासागरमा सन् १९१९ अप्रिल १४मा टाइटानिक पानी जहाज डुबेको थियो।', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'निम्न मध्ये कुन ठीक छ ?\nक. अशारा रेखाले कुनै ठाउँको हावापानीको अवस्था यहाँ पाउन सकिन्छ।\nख. मौरिससको राजधानी मोगासु हो।\nग. एण्डेज भरना दक्षिण अमेरिकामा रहेको छ।\nघ. युरोपा पर्वत भूखण्ड अफ्रिकामा पर्दछ।', E'क र ग ठिक हुन्', E'क र घ ठिक हुन्', E'ख र ग ठिक हुन्', E'घ र ग ठिक हुन्', 'A', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'राष्ट्रिय जनगणना, २०७८ को आधारमा जनसङ्ख्याको हिसाबले तलका मध्ये ठूलो उपमहानगरपालिका कुन हो ?', E'बुटवल', E'धरोही', E'तुलसीपुर', E'नेपालगञ्ज', 'B', E'सबैभन्दा बढी जिल्लासँग सिमाना जोडिएको जिल्ला सिन्धुली हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 5, E'नदी र तीनको लम्बाइको सही जोडा कुन हो ?\nक. कर्णाली - १) २२३ कि.मि.\nख. कोशी - २) १६३ कि.मि.\nग. बागमती - ३) ३२० कि.मि.\nघ. महाकाली - ४) २०३ कि.मि.', E'क-१, ख-२, ग-३, घ-४', E'क-२, ख-४, ग-१, घ-१', E'क-१, ख-३, ग-२, घ-४', E'क-१, ख-२, ग-२, घ-१', 'D', E'इन्द्रचा खोलाको पौराणिक नाम इच्छुमती हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 6, E'नेपाल संवत्को बारेमा उपयुक्त भनाई पहिचान गर्नुहोस्।\n१) नेपाल संवत्लाई प्रचलनमा ल्याउने शङ्खधर साख्वा (मल्लकालीन राजा राघव देवको पालामा)\n२) नेपाल संवत्लाई राष्ट्रिय संवत्को मान्यता पाएको २०६५ कार्तिक ०८ (प्रधानमन्त्री पुष्प कमल दाहालको पालामा)\n३) सरकारी कागजातमा नेपाल संवत् अनिवार्य लेख्ने सरकारको निर्णय २०८० कार्तिक २७ (प्रधानमन्त्री पुष्पकमल दाहालको पालामा)\n४) हाल नेपाल संवत्ले रहेको नेपाल सम्बत् ११४५ (२०८१ कार्तिक १७ अर्थात आर्तिक शुक्ल प्रतिपदा देखि)', E'१, २ ठिक है, ३ गलत', E'१ र बेठिक, ३ ठिक', E'१, २, ३ सबै गलत', E'१, २, ३ सबै ठिक', 'D', E'', 'nepali', true, NULL, NULL),
