      (v_set_id, 46, E'१ लिटर दुधलाई १/४ अट्ने सिसिमा भरि राख्दा कतिवटा सिसि भर्न सकिएला ?', E'१६ वटा', E'२० वटा', E'१५ वटा', E'१७ वटा', 'A', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 47, E'समूहमा नमिल्नेको पत्ता लगाउनुहोस् ।', E'मुद्रक', E'प्रकाशक', E'लेखक', E'पाठक', 'D', E'', 'nepali', true, NULL, NULL),
