      (v_set_id, 2, E'दिइएकाको मध्ये कुन जोडा गलत छ ?', E'राष्ट्रिय शिक्षा दिवसः असोज २', E'अन्तर्राष्ट्रिय शिक्षा दिवसः सेप्टेम्बर ८', E'अन्तर्राष्ट्रिय शिक्षा दिवसः जनवरी २४', E'राष्ट्रिय बाल दिवसः भाद्र २९', 'B', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 3, E'विश्वको दोस्रो ठूलो महासागर कुन हो ?', E'प्रशान्त महासागर', E'हिन्द महासागर', E'आन्ध्र महासागर', E'सुमेरु महासागर', 'C', E'प्रशान्त महासागरको सबैभन्दा गहिरो भाग मरियाना ट्रेन्च हो।', 'nepali', true, NULL, NULL),
      (v_set_id, 4, E'कथन अध्ययन गरी सही उत्तर छनोट गर्नुहोस्।\nA. नेपालको सरदर चौडाई १९३ कि.मि. रहेको छ।\nB. नेपालको पूर्व पश्चिम लम्बाई ८८५ कि.मि. रहेको छ।', E'A ठीक B बेठिक', E'A बेठिक B ठीक', E'दुवै ठीक', E'दुवै बेठिक', 'C', E'', 'nepali', true, NULL, NULL),
