      (v_set_id, 11, E'नेपालको सिमसार क्षेत्रमा तलका मध्ये कुन पर्दैन ?', E'चितवनको बीस-हजारी ताल', E'मुगुको रारा ताल', E'ईलामको माईपोखरी', E'भोजपुरको साल्पा पोखरी', 'D', E'विश्वभरीको सिमसार क्षेत्रको संरक्षणका लागि इरानको रामसार भन्ने ठाउँमा रामसार कन्भेनसन (महासन्धि) मा सन् १९७१ फेब्रुअरी २ मा हस्ताक्षर भएको थियो।', 'nepali', true, NULL, NULL),
      (v_set_id, 12, E'पृथ्वीको कुन वायुमण्डलीय तहलाई ओजन तहको भनिन्छ ?', E'समताप मण्डल', E'मध्ये मण्डल', E'निम्नतम मण्डल', E'आयत मण्डल', 'A', E'', 'nepali', true, NULL, NULL),
      (v_set_id, 13, E'संयुक्त राष्ट्र सङ्घमा नेपालको प्रतिनिधित्व बारे कुन भनाई गलत छ ?', E'संयुक्त राष्ट्र सङ्घमा लागि नेपालको पहिलो प्रतिनिधि ऋषिकेश शाह हुन्।', E'संयुक्त राष्ट्र सङ्घले सबैभन्दा बढी आर्थिक भार पहिलो व्यक्ति: चूडाप्रसाद शर्मा हुन्।', E'नेपालले संयुक्त राष्ट्रको शान्ति स्थापना मिसनमा सन् १९५८ बाट भाग लिन थालेको हो।', E'संयुक्त राष्ट्र सङ्घको महासभामा सम्बोधन गर्ने पहिलो प्रधानमन्त्री टंक प्रसाद आचार्य हुन्।', 'D', E'', 'nepali', true, NULL, NULL),
