      (v_set_id, 5, E'भैरव ठाकुरी पनि भनिने नुपाल हिमाल कुन जिल्लामा अवस्थित छ ?', E'डोल्पा', E'मुस्ताङ', E'सोलुखुम्बु', E'सिन्धुपाल्चोक', 'D', E'सिमलोला पर्वत ताप्लेजुङ जिल्लामा पर्दछ।', 'nepali', true, NULL, NULL),
      (v_set_id, 6, E'विदेहको मध्य सही जोडा कुन हैन ?', E'सामाजिक सुधारक → जयस्थिति मल्ल', E'कविन्द्र → प्रताप मल्ल', E'जिवित राजा → योगनरेन्द्र मल्ल', E'सुमती → भुपालेन्द्र मल्ल', 'D', E'', 'nepali', true, NULL, NULL),
