  INSERT INTO public.question_set_questions (question_set_id, question_id, position)
  SELECT v_set_id, id, order_number FROM ins;

  -- Tag every question in this past-paper set
  INSERT INTO public.question_tags (question_id, tag_id)
  SELECT q.id, (SELECT id FROM public.tags WHERE slug = 'past-paper')
  FROM public.questions q WHERE q.set_id = v_set_id
  ON CONFLICT DO NOTHING;

  -- Surface in the topic list (unlocked — mock exams are not a gated sequence)
  SELECT COALESCE(MAX(step_order), 0) + 1 INTO v_next_step
  FROM public.topic_learning_paths WHERE topic_id = v_topic_id;
  INSERT INTO public.topic_learning_paths (topic_id, question_set_id, step_order, is_locked)
  VALUES (v_topic_id, v_set_id, v_next_step, false);

  RAISE NOTICE 'IMPORTED: % (% Qs)', E'निमावि प्रथम पत्र — विगत प्रश्नपत्र: निमावि तह २०८०', 50;
END $$;

-- ─────────────────────────────────────────────────────────────────────
-- निमावि प्रथम पत्र — विगत प्रश्नपत्र: निमावि तह २०८१  (50 questions)
-- ─────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_topic_id  uuid;
  v_set_id    uuid;
  v_existing  uuid;
  v_next_step int;
BEGIN
  SELECT t.id INTO v_topic_id
  FROM public.topics t
  JOIN public.subjects s ON s.id = t.subject_id
  JOIN public.modules  m ON m.id = s.module_id
  WHERE m.slug = 'nimavi-pratham-patra' AND s.slug = 'abhyas' AND t.slug = 'vigat-prashnapatra'
  LIMIT 1;

  IF v_topic_id IS NULL THEN
    RAISE EXCEPTION 'Topic % not found (scaffold block must run first)', 'vigat-prashnapatra';
  END IF;

  SELECT id INTO v_existing FROM public.question_sets
  WHERE title = E'निमावि प्रथम पत्र — विगत प्रश्नपत्र: निमावि तह २०८१' AND topic_id = v_topic_id LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RAISE NOTICE 'SKIP existing set: %', E'निमावि प्रथम पत्र — विगत प्रश्नपत्र: निमावि तह २०८१';
    RETURN;
  END IF;

